from ..sl4a import Result as _Rst
import os,shutil
from time import sleep,time
_per = "com.termux.permission.RUN_COMMAND"

class termux:
    def __init__( this, sup ):
        global _swapCont
        p=__file__[:__file__.rfind('/')+1]
        k='termux'
        for i in dir(this):
            if i[0] == '_':
                continue
            r=f"{p}{i}.txt"
            if os.path.exists(r):
                j=open(f"{p}{i}.txt").read()
                exec(f'{k}.{i}.__doc__=j')
            else:
                exec(f'{k}.{i}.__doc__=sup.{k}{i}.__doc__')
            exec(f'sup.{k}{i}=this.{i}')
        _swapCont = open(p+'swapCont.txt').read()
        this._rpc = sup._rpc
        this._sup = sup
        del i,j,p,r,k

    def StartService(self, virtualRoot = "/com.termux"):
        self._rpc('backgroundProtect')
        result = {"QPython Start Termux Service" : time()}
        s = 'has been '
        if _per in self._rpc("checkPermissions").result['granted']:
            result[_per] = s + 'granted'
        else:
            self._rpc('requestPermissions',_per)
            n = 10
            while n > 0:
                sleep(1)
                n -= 1
                if _per in self._rpc("checkPermissions").result['granted']:
                    result[_per] = s + 'requested'
                    break
            if n <= 0:
                result[_per] = s + 'rejected'
                return self._err(result)

        if not self._rpc('documentFileListFiles',virtualRoot).result:
            self._rpc('makeToast','Choose Termux Root and give permission',1,None)
        uri = self._rpc('documentTreeShowOpen',virtualRoot)
        result ["Termux URI"] = uri
        if uri.error != None:
            return self._err(result)
        s = virtualRoot + '/.termux/termux.properties'
        n = self._rpc('documentFileInputStream', s, 'utf-8').result
        i = '\nallow-external-apps = true\n'
        if n.find(i) >= 0:
            n = 0
        else:
            k = n.replace(f'\n# {i[1:]}',i)
            if n == k:
                k += i
            n = self._rpc('documentFileOutputStream', s, k, 'utf-8')
        result["Termux Property Change"] = {
        'termux uri' : self._rpc('documentFileGetUri', s),
        'virtual path': s,
        'write length' : n
        }
        
        return self._rst(result)

    def RunCommand(self, path, args = [], workdir = None, background = False):

        i = not background
        if workdir == None:
            workdir = '/data/data/com.termux/files/home'

        result = {}
        result["startService"] = self._rpc('startService',
            'com.termux.RUN_COMMAND',
            None,None,
            {
                'com.termux.RUN_COMMAND_PATH':path,
                'com.termux.RUN_COMMAND_ARGUMENTS':args,
                'com.termux.RUN_COMMAND_WORKDIR':workdir,
                'com.termux.RUN_COMMAND_BACKGROUND':background
      },
            i,'com.termux',
            'com.termux.app.RunCommandService'
        )

        if i:
            result["launch"] = self._rpc(
                'launch',None,'com.termux',False
            )
        
        return self._rst(result)

    def _qsl4aExportTo(self, swapPath):
        sep = time()

        env = os.environ
        ah = 'androidhelper'
        sl4aPath = os.path.realpath(env['HOME'][:-5] + ah)
        path = os.path.realpath(swapPath)
        if os.path.exists(path):
            shutil.rmtree(path)
        if path[-1:] != '/':
            path += '/'  
        pa = path + ah
        ps = pa + '/sl4a.py'
        if os.path.exists(pa):
            return self._err('QSL4A Export Target Exists .')
        if not os.path.exists(path):
            os.makedirs(path)

        shutil.copytree(sl4aPath,pa)
    
        env = repr(env['AP_PORT']),repr(env['AP_HOST']),repr(env['AP_HANDSHAKE'])
        tx = open(ps).read().replace("""
PORT = os.environ.get('AP_PORT')
HOST = os.environ.get('AP_HOST')
HANDSHAKE = os.environ.get('AP_HANDSHAKE')
""",f"""
PORT = {env[0]}
HOST = {env[1]}
HANDSHAKE = {env[2]}
""")
        open(ps,'w').write(tx)
        
        tx = open(sl4aPath[:-6] + '.py').read().replace("k('AP_HOST'),k('AP_PORT')",f"{env[1]},{env[0]}").replace("k('AP_HANDSHAKE')",env[2])
        open(pa[:-6] + '.py','w').write(tx)
    
        open(path + 'setup.py','w').write(_swapCont)
        
        ah = 'fullscreenwrapper.py'
        shutil.copy(sl4aPath[:-13] + ah, path + ah)

        sep = time() - sep
        return self._rst({'swapPath': path, 'exportTime': sep})

    def GetQSL4A(self, swapPath = None, autoSetup = True):
        result = {"Termux Get QPython SL4A Service" : time()}
        result["launch"] = self._rpc(
            'launch',None,'com.termux',False
        )
        if not swapPath:
            swapPath = '/sdcard/Android/media/com.termux/QPython SL4A Swap'
        sep = self._qsl4aExportTo(swapPath)
        result["qsl4aExportToSwap"] = sep
        if autoSetup:
            n = 1
            k = 'TermuxQSL4AService'
            sep = max(sep.result['exportTime'] * 3, 1)
            while n <= 3:
                result["termuxRunSetupCommand%s"%n] = self.RunCommand('/data/data/com.termux/files/usr/bin/python', [swapPath + '/setup.py'])
                sleep(n * sep)
                i = self._rpc('sharedVariableRemove',k)
                result[k + str(n)] = i
                if i.result != None:
                    break
                n+=1
        return self._rst(result)
    
    def _rst(self, result):
        self = self._sup
        r = _Rst(self._id, result, None)
        self._id += 1
        return r
    
    def _err(self, error):
        self = self._sup
        r = _Rst(self._id, None, error)
        self._id += 1
        return r

